private void testSourceConfig(boolean fallbackMR, boolean inferParallelism) throws Exception {
    HiveDynamicTableFactory tableFactorySpy = spy((HiveDynamicTableFactory) hiveCatalog.getFactory().get());
    doAnswer(invocation -> {
        DynamicTableFactory.Context context = invocation.getArgument(0);
        assertThat(context.getConfiguration().get(HiveOptions.TABLE_EXEC_HIVE_FALLBACK_MAPRED_READER)).isEqualTo(fallbackMR);
        return new TestConfigSource(new JobConf(hiveCatalog.getHiveConf()), context.getConfiguration(), context.getObjectIdentifier().toObjectPath(), context.getCatalogTable(), inferParallelism);
    }).when(tableFactorySpy).createDynamicTableSource(any(DynamicTableFactory.Context.class));
    HiveCatalog catalogSpy = spy(hiveCatalog);
    doReturn(Optional.of(tableFactorySpy)).when(catalogSpy).getTableFactory();
    TableEnvironment tableEnv = HiveTestUtils.createTableEnvInBatchMode();
    tableEnv.getConfig().set(HiveOptions.TABLE_EXEC_HIVE_FALLBACK_MAPRED_READER, fallbackMR);
    tableEnv.getConfig().set(HiveOptions.TABLE_EXEC_HIVE_INFER_SOURCE_PARALLELISM, inferParallelism);
    tableEnv.getConfig().set(ExecutionConfigOptions.TABLE_EXEC_RESOURCE_DEFAULT_PARALLELISM, 2);
    tableEnv.registerCatalog(catalogSpy.getName(), catalogSpy);
    tableEnv.useCatalog(catalogSpy.getName());
    List<Row> results = CollectionUtil.iteratorToList(tableEnv.sqlQuery("select * from db1.src order by x").execute().collect());
    assertThat(results.toString()).isEqualTo("[+I[1, a], +I[2, b]]");
}

