    RemoteInputChannel rich = addInputChannel(handler);
    final Throwable[] error = new Throwable[1];
    // Verify the Exception
    doAnswer((Answer<Void>) invocation -> {
        Throwable cause = (Throwable) invocation.getArguments()[0];
        try {
