        } catch (Throwable t) {
            error[0] = t;
        }
        return null;
    }).when(rich).onError(any(Throwable.class));
    ch.pipeline().fireExceptionCaught(new IOException("Connection reset by peer"));
    assertThat(error[0]).isNull();
}

