/**
 * Verifies remote closes trigger the release of all resources.
 */
@Test
void testRemoteClose() throws Exception {
    final TestPooledBufferProvider outboundBuffers = new TestPooledBufferProvider(16);
    final CountDownLatch sync = new CountDownLatch(1);
    final ResultPartitionManager partitionManager = mock(ResultPartitionManager.class);
    when(partitionManager.createSubpartitionViewOrRegisterListener(any(ResultPartitionID.class), any(ResultSubpartitionIndexSet.class), any(BufferAvailabilityListener.class), any(PartitionRequestListener.class))).thenAnswer((Answer<Optional<ResultSubpartitionView>>) invocationOnMock -> Optional.of(new CancelPartitionRequestTest.InfiniteSubpartitionView(outboundBuffers, sync)));
    NettyProtocol protocol = new NettyProtocol(partitionManager, mock(TaskEventDispatcher.class)) {

        @Override
        public ChannelHandler[] getClientChannelHandlers() {
            return new ChannelHandler[] { new NettyMessage.NettyMessageEncoder(), // Close on read
            new ChannelInboundHandlerAdapter() {

                @Override
                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                    ctx.channel().close();
                }
            } };
        }
    };
    NettyTestUtil.NettyServerAndClient serverAndClient = null;
    try {
        serverAndClient = initServerAndClient(protocol);
        Channel ch = connect(serverAndClient);
        // Write something to trigger close by server
        ch.writeAndFlush(new NettyMessage.PartitionRequest(new ResultPartitionID(), new ResultSubpartitionIndexSet(0), new InputChannelID(), Integer.MAX_VALUE));
        // Wait for the notification
        assertThat(sync.await(TestingUtils.TESTING_DURATION.toMillis(), TimeUnit.MILLISECONDS)).withFailMessage("Timed out after waiting for " + TestingUtils.TESTING_DURATION.toMillis() + " ms to be notified about released partition.").isTrue();
    } finally {
        shutdown(serverAndClient);
    }
}

