@Test
void testPartitionRequestExponentialBackoff() throws Exception {
    // Config
    int initialBackoff = 500;
    int maxBackoff = 3000;
    // Start with initial backoff, then keep doubling, and cap at max.
    int[] expectedDelays = { initialBackoff, 1000, 2000, maxBackoff };
    // Setup
    SingleInputGate inputGate = mock(SingleInputGate.class);
    BufferProvider bufferProvider = mock(BufferProvider.class);
    when(inputGate.getBufferProvider()).thenReturn(bufferProvider);
    ResultPartitionManager partitionManager = mock(ResultPartitionManager.class);
    LocalInputChannel ch = createLocalInputChannel(inputGate, partitionManager, initialBackoff, maxBackoff);
    when(partitionManager.createSubpartitionView(eq(ch.partitionId), any(ResultSubpartitionIndexSet.class), any(BufferAvailabilityListener.class))).thenThrow(new PartitionNotFoundException(ch.partitionId));
    Timer timer = mock(Timer.class);
    doAnswer((Answer<Void>) invocation -> {
        ((TimerTask) invocation.getArguments()[0]).run();
        return null;
    }).when(timer).schedule(any(TimerTask.class), anyLong());
    // Initial request
    ch.requestSubpartitions();
    verify(partitionManager).createSubpartitionView(eq(ch.partitionId), any(ResultSubpartitionIndexSet.class), any(BufferAvailabilityListener.class));
    // Request subpartition and verify that the actual requests are delayed.
    for (long expected : expectedDelays) {
        ch.retriggerSubpartitionRequest(timer);
        verify(timer).schedule(any(TimerTask.class), eq(expected));
    }
    // Exception after backoff is greater than the maximum backoff.
    ch.retriggerSubpartitionRequest(timer);
    assertThatThrownBy(ch::getNextBuffer);
}

