/**
 * Tests that the replace state handle is discarded if ZooKeeper setData fails.
 */
@Test
void testReplaceDiscardStateHandleAfterFailure() throws Exception {
    // Setup
    final TestingLongStateHandleHelper stateHandleProvider = new TestingLongStateHandleHelper();
    CuratorFramework client = spy(getZooKeeperClient());
    when(client.setData()).thenThrow(new RuntimeException("Expected test Exception."));
    ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> store = new ZooKeeperStateHandleStore<>(client, stateHandleProvider);
    // Config
    final String pathInZooKeeper = "/testReplaceDiscardStateHandleAfterFailure";
    final long initialState = 30968470898L;
    final long replaceState = 88383776661L;
    // Test
    store.addAndLock(pathInZooKeeper, new TestingLongStateHandleHelper.LongStateHandle(initialState));
    assertThatExceptionOfType(Exception.class).as("Did not throw expected exception").isThrownBy(() -> store.replace(pathInZooKeeper, IntegerResourceVersion.valueOf(0), new TestingLongStateHandleHelper.LongStateHandle(replaceState)));
    // Verify
    // State handle created and discarded
    assertThat(TestingLongStateHandleHelper.getGlobalStorageSize()).isEqualTo(2);
    assertThat(TestingLongStateHandleHelper.getStateHandleValueByIndex(0)).isEqualTo(initialState);
    assertThat(TestingLongStateHandleHelper.getStateHandleValueByIndex(1)).isEqualTo(replaceState);
    assertThat(TestingLongStateHandleHelper.getDiscardCallCountForStateHandleByIndex(0)).isZero();
    assertThat(TestingLongStateHandleHelper.getDiscardCallCountForStateHandleByIndex(1)).isZero();
    // Initial value
    @SuppressWarnings("unchecked")
    final long actual = ((RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle>) InstantiationUtil.deserializeObject(getZooKeeperClient().getData().forPath(pathInZooKeeper), ClassLoader.getSystemClassLoader())).retrieveState().getValue();
    assertThat(actual).isEqualTo(initialState);
}

