public <K> RocksDBKeyedStateBackend<K> create(TemporaryFolder tmp, TypeSerializer<K> keySerializer, int maxKeyGroupNumber) throws Exception {
    RocksDBStateBackend backend = getRocksDBStateBackend(tmp);
    env = MockEnvironment.builder().build();
    JobID jobID = new JobID();
    KeyGroupRange keyGroupRange = new KeyGroupRange(0, maxKeyGroupNumber - 1);
    TaskKvStateRegistry kvStateRegistry = mock(TaskKvStateRegistry.class);
    CloseableRegistry cancelStreamRegistry = new CloseableRegistry();
    keyedStateBackend = (RocksDBKeyedStateBackend<K>) backend.createKeyedStateBackend(new KeyedStateBackendParametersImpl<>(env, jobID, "Test", keySerializer, maxKeyGroupNumber, keyGroupRange, kvStateRegistry, TtlTimeProvider.DEFAULT, new UnregisteredMetricsGroup(), Collections.emptyList(), cancelStreamRegistry));
    return (RocksDBKeyedStateBackend<K>) keyedStateBackend;
}

