    @SuppressWarnings("unchecked")
    InternalWindowFunction<Iterable<Integer>, List<Integer>, Integer, TimeWindow> mockWindowFunction = mock(InternalWindowFunction.class);
    KeyedOneInputStreamOperatorTestHarness<Integer, Integer, List<Integer>> testHarness = createWindowOperator(mockAssigner, mockTrigger, 0L, mockWindowFunction);
    testHarness.open();
