private void testTimerCreationAndDeletion(TimeDomainAdaptor timeAdaptor) throws Exception {
    WindowAssigner<Integer, TimeWindow> mockAssigner = mockTimeWindowAssigner();
    timeAdaptor.setIsEventTime(mockAssigner);
