    MergeCallback<TimeWindow, Collection<TimeWindow>> callback = mock(MergeCallback.class);
    SessionWindowAssigner assigner = SessionWindowAssigner.withGap(Duration.ofMillis(5000));
    TreeSet<TimeWindow> sortedWindows = new TreeSet<>();
    sortedWindows.addAll(Arrays.asList(new TimeWindow(1, 4), new TimeWindow(5, 7), new TimeWindow(9, 10)));
    assigner.mergeWindows(new TimeWindow(3, 6), sortedWindows, callback);
    verify(callback, times(1)).merge(eq(new TimeWindow(1, 7)), argThat((ArgumentMatcher<Collection<TimeWindow>>) timeWindows -> containsInAnyOrder(new TimeWindow(1, 4), new TimeWindow(5, 7), new TimeWindow(3, 6)).matches(timeWindows)));
}

@Test
public void testAssignerIsInvokedOncePerElement() throws Exception {
    GroupWindowAssigner<TimeWindow> mockAssigner = mockTimeWindowAssigner();
    Trigger<TimeWindow> mockTrigger = mockTrigger();
    NamespaceAggsHandleFunction<TimeWindow> mockAggregate = mockAggsHandleFunction();
    OneInputStreamOperatorTestHarness<RowData, RowData> testHarness = createWindowOperator(mockAssigner, mockTrigger, mockAggregate, 0L);
    testHarness.open();
    when(mockAssigner.assignWindows(any(), anyLong())).thenReturn(Collections.singletonList(new TimeWindow(0, 0)));
    testHarness.processElement(insertRecord("String", 1, 0L));
    verify(mockAssigner, times(1)).assignWindows(eq(row("String", 1, 0L)), eq(0L));
    testHarness.processElement(insertRecord("String", 1, 0L));
    verify(mockAssigner, times(2)).assignWindows(eq(row("String", 1, 0L)), eq(0L));
}

